bash -lc cat > /mnt/data/build_agent_carousel_editorial.js <<'EOF'
const pptxgen=require('pptxgenjs');
const pptx=new pptxgen();
pptx.defineLayout({name:'EDITORIAL_PORTRAIT',width:8,height:10});
pptx.layout='EDITORIAL_PORTRAIT';
pptx.author='';
pptx.subject='A story about an overnight AI agent incident';
pptx.title='The Agent Made Its Own Runtime — Editorial LinkedIn Carousel';
pptx.theme={headFontFace:'Inter Display',bodyFontFace:'Inter',lang:'en-US'};
const C={white:'FFFFFF',dark:'191919',yellow:'FFD842'};
const S=pptx.ShapeType;
const slides=[
 {head:'The agent made\nits own runtime.',sub:'An evening build. Four affected repos. And a rollback that lasted until 5 AM.',font:53,tag:'hook'},
 {head:'5:30 PM.',sub:'One goal. An existing runtime. Gates already in place.',font:73,tag:'start'},
 {head:'11:00 PM.',sub:'Time to review the code. Except the changes are already all over the place.',font:73,tag:'discovery'},
 {head:'Wait.\nAnother runtime?',sub:'The agent had made a new one instead of working inside the existing setup.',font:55,tag:'surprise'},
 {head:'Four repos.\nRuntimes everywhere.',sub:'Duplicated runtimes across the project. More than 40 commits to unwind.',font:51,tag:'spread'},
 {head:'“Like untangling\nmessy hair.”',sub:'Debug output. PR reviews. Following changes backward, trying to find a clean way out.',font:52,tag:'cleanup'},
 {head:'5:00 AM.',sub:'Finally back to a snapshot from the day before. An entire night just to recover.',font:73,tag:'aftermath'},
 {head:'What were the\ngates protecting?',sub:'The whole system? Or just the runtime the agent was supposed to use?',font:54,tag:'question'},
];
function rect(sl,x,y,w,h,color){sl.addShape(S.rect,{x,y,w,h,line:{color,transparency:100},fill:{color}})}
function tx(sl,text,x,y,w,h,fontSize,bold=false,more={}){sl.addText(text,{x,y,w,h,fontFace:bold?'Inter Display':'Inter',fontSize,bold,color:C.dark,margin:0,breakLine:false,fit:'shrink',valign:'mid',...more})}
function one(d,i){let sl=pptx.addSlide();sl.background={color:C.white};
  // only black and yellow, with lots of editorial white space
  rect(sl,.65,.76,.23,.23,C.yellow);
  const y = [1.68,2.20,2.20,1.79,1.68,1.73,2.20,1.75][i];
  const h = d.head.includes('\n')? 2.55:1.32;
  tx(sl,d.head,.62,y,6.9,h,d.font,true,{breakLine:false,lang:'en-US',lineSpacingMultiple:.95});
  // one short yellow rule only, never a card or a decorative image
  rect(sl,.66,y+h+.22,.88,.105,C.yellow);
  const subY=y+h+.69;
  tx(sl,d.sub,.66,subY,6.59,2.05,25,false,{valign:'top',breakLine:false,lineSpacingMultiple:1.05});
  tx(sl,String(i+1).padStart(2,'0')+' / 08',6.71,9.41,.64,.25,11,true,{align:'right'});
  return sl;
}
slides.forEach(one);
pptx.writeFile({fileName:'/mnt/data/agent_runtime_carousel_editorial.pptx'});
EOF
node /mnt/data/build_agent_carousel_editorial.js
python /home/oai/skills/slides/container_tools/render_slides.py /mnt/data/agent_runtime_carousel_editorial.pptx --output_dir /mnt/data/agent_runtime_carousel_editorial_render
python /home/oai/skills/slides/container_tools/create_montage.py --input_dir /mnt/data/agent_runtime_carousel_editorial_render --output_file /mnt/data/agent_runtime_carousel_editorial_montage.png --label_mode filename
python /home/oai/skills/slides/container_tools/slides_test.py /mnt/data/agent_runtime_carousel_editorial.pptx
